"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["35229"],{79372(e){e.exports=JSON.parse('{"id":"FIN-779","slug":"open-market-operations","term":"Open Market Operations","also_known_as":[],"difficulty":"Intermediate","definition":"Open market operations are the buying and selling of government securities or other assets by a central bank in financial markets, to manage the money supply and keep short-term interest rates close to its policy rate.","explanation":["Open market operations are one of the main tools central banks use to implement monetary policy day to day.","When a central bank buys securities, such as government bonds, from banks, it pays for them by adding money to the banks\' reserve accounts. This increases the amount of money in the banking system, which tends to push short-term interest rates down. When it sells securities, it takes money out of the system, which tends to push rates up.","For example, if short-term market rates are drifting above the central bank\'s target, it can buy securities to add money to the system and bring rates back down.","Many open market operations are temporary, carried out through repurchase agreements, where the central bank buys securities and agrees to sell them back shortly afterwards. Large-scale, long-term purchases of assets, designed to lower longer-term interest rates when the policy rate is already very low, are known as quantitative easing."],"note":"","total":1500,"prev":{"slug":"open-finance","term":"Open Finance"},"next":{"slug":"operating-cash-flow","term":"Operating Cash Flow"}}')}}]);